SELECT DISTINCT sm.id, sm.redirect, sm.be_hidden,sm.be_unauth, sm.menu_name, sm.priority, sm.icon, sm.parent_id, ra.req_url FROM sys_menu sm LEFT JOIN sys_role_resource rr ON sm.id = rr.resource_id AND rr.resource_type = 'MENU' LEFT JOIN sys_role r ON rr.role_id = r.id INNER JOIN sys_resource_api ra ON sm.id = ra.resource_id AND ra.resource_type = 'MENU'
(sm.be_unauth = 0 AND r.id in
#{item}
)
OR (sm.be_unauth = 1)
ORDER BY sm.priority ,sm.parent_id ASC

SELECT DISTINCT sm.id, sm.redirect, sm.be_hidden, sm.menu_name, sm.priority, sm.icon, sm.parent_id, ra.req_url FROM sys_menu sm LEFT JOIN sys_role_resource rr ON sm.id = rr.resource_id AND rr.resource_type = 'MENU' LEFT JOIN sys_role r ON rr.role_id = r.id INNER JOIN sys_resource_api ra ON sm.id = ra.resource_id AND ra.resource_type = 'MENU'
sm.menu_type = #{menuType,jdbcType=CHAR}
ORDER BY sm.priority ,sm.parent_id ASC

SELECT DISTINCT m.id,m.menu_name,m.parent_id,m.be_lock,m.menu_type,m.priority FROM sys_menu m INNER JOIN sys_resource_api ra ON (ra.resource_id = m.id AND ra.resource_type = 'MENU') LEFT JOIN sys_role_resource srr ON (srr.resource_id = m.id AND srr.resource_type = 'MENU') WHERE m.be_unauth = 0 and srr.role_id in
#{item}
ORDER BY m.menu_type, m.priority ASC

SELECT DISTINCT sb.id, sb.button_name, sb.be_unauth, sb.sub_menu, sb.menu_id,sb.be_lock
FROM sys_button sb
WHERE sb.be_unauth = 0 and sb.menu_id = #{menuId}

SELECT DISTINCT sb.id, sb.button_name,sb.be_unauth, sb.sub_menu, sb.menu_id, bp.id as perm_id, bp.perm_action FROM sys_button sb INNER JOIN sys_role_resource srr ON sb.id = srr.resource_id AND srr.resource_type = 'BUTTON' INNER JOIN sys_user_role ur ON ur.role_id = srr.role_id LEFT JOIN sys_business_perm bp ON bp.button_id = sb.id
sb.be_unauth = 1 OR ( sb.be_unauth = 0 AND ur.role_id in
#{item}
)

SELECT bp.id as perm_id,IFNULL(sbp.perm_scope, 'CURRENT_USER') AS perm_scope, sbp.perm_start_time, sbp.perm_end_time, bp.perm_action FROM sys_business_perm bp LEFT JOIN sys_uset_business_perm sbp ON sbp.perm_id = bp.id
bp.id = #{permId} AND sbp.uset_id IN
#{item}
